#include <atomic>
#include <vector>
#include <new>

template <class Event>
struct Ring {
    explicit Ring(size_t n) : mask(n - 1), slots(n) {}
    size_t mask;
    std::vector<Event> slots;                 // pre-allocated, reused forever
    alignas(64) std::atomic<long> cursor{-1};  // last published sequence
    Event& at(long seq) { return slots[seq & mask]; }
};

// Producer: claim -> fill in place -> publish (release)
template <class Event>
void publish(Ring<Event>& r, long& nextSeq, const Event& src) {
    long seq = ++nextSeq;                      // single producer: just increment
    r.at(seq) = src;                           // fill the existing slot, no alloc
    r.cursor.store(seq, std::memory_order_release);
}

// Consumer with its own sequence + a barrier (here: just the producer cursor)
template <class Event, class Handler>
void consume(Ring<Event>& r, std::atomic<long>& mySeq, Handler&& h) {
    long next = mySeq.load(std::memory_order_relaxed) + 1;
    long avail = r.cursor.load(std::memory_order_acquire);   // barrier
    for (; next <= avail; ++next)               // BATCH: catch up in one loop
        h(r.at(next), next, next == avail /*endOfBatch*/);
    mySeq.store(avail, std::memory_order_release);
}
